// 无DOM依赖的教学流程生成器，便于验证封装与解封装。
export function buildJourney(ls,scenario){const udp=scenario==='dns';const trans=udp?'UDP':'TCP',app=udp?'DNS query':'HTTP request';const n=ls.length;let headers=[{text:app,kind:'payload'}];const steps=[];
 const appLayer=l=>l.id==='application'||l.id==='tcp-application';const transport=l=>l.id.includes('transport');const network=l=>l.id==='network'||l.id==='internet';const link=l=>l.id==='datalink'||l.id==='interface';
 for(let i=0;i<n;i++){const l=ls[i];let description;if(appLayer(l))description=udp?'Create a DNS A query and pass it to UDP. The server address is already known; full preliminary resolution is not demonstrated.':'Create an HTTP request. To expose layers clearly, this example uses HTTP without TLS and an already established TCP connection.';else if(transport(l)){headers.unshift({text:`${trans} header · 53000 → ${udp?53:80}`,kind:'transport'});description=`Add a ${trans} header; ports distinguish sending and receiving endpoints. ${udp?'UDP preserves datagram boundaries without its own acknowledgments or retransmission.':'TCP carries an ordered byte stream without application message boundaries.'}`;}else if(network(l)){headers.unshift({text:'IP header · TTL 64',kind:'network'});description='Add an IP header: 192.168.1.10 → 192.168.2.20. The destination is remote; the next hop is the local gateway.';}else if(link(l)){headers.unshift({text:'Frame header · A → R-left',kind:'link'});headers.push({text:'FCS',kind:'link'});description='The first Ethernet frame targets the router left-interface MAC and originates at A. ARP information is assumed known.';if(l.id==='interface')description+=' The network access layer also encodes frames as signals.';}else if(l.id==='physical')description='Encode the frame into electrical, optical or wireless signals on the first link. The physical layer adds no ordinary application-style header.';else description=l.id==='presentation'?'Perform required representation processing without inventing a fixed presentation-layer header.':'The application manages interaction state. This is a functional stage, not a fixed session-layer header.';steps.push({title:`Sender · ${l.name}`,description,layer:i,host:0,headers:headers.map(x=>({...x})),tag:l.unit});}
 const ipHeaders=headers.filter(h=>h.kind!=='link').map(h=>h.kind==='network'?{...h,text:'IP header · TTL 63'}:{...h});
 steps.push({title:'Router · Inspect IP and select next hop',description:'Remove the first frame, route by destination IP and decrement TTL from 64 to 63. Without NAT, IP addresses remain unchanged. Normal routers do not decapsulate the application.',router:true,layer:ls.findIndex(network),headers:ipHeaders,tag:'IP routing · TTL 63'});
 const secondHeaders=[{text:'Frame header · R-right → B',kind:'link'},...ipHeaders,{text:'FCS',kind:'link'}];
 steps.push({title:'Second link · Re-encapsulate and send',description:'Use the router right-interface MAC as source and host B MAC as destination, regenerate FCS and send. Links may use different technologies.',bridge:true,layer:n-1,headers:secondHeaders,tag:'New frame · R-right → B'});
 headers=secondHeaders.map(x=>({...x}));
 for(let i=n-1;i>=0;i--){const l=ls[i];let description;if(l.id==='physical')description='B receives signals, recovers bits and passes them to the link layer for framing.';else if(link(l)){headers=headers.filter(h=>h.kind!=='link');description='Check the destination link address and FCS. Remove this hop of headers/trailer and deliver the IP packet upward.';}else if(network(l)){headers=headers.filter(h=>h.kind!=='network');description='Confirm that the destination IP belongs to B and use the protocol identifier to pass payload to TCP or UDP.';}else if(transport(l)){headers=headers.filter(h=>h.kind!=='transport');description=udp?'Destination port 53 selects the DNS application. This datagram arrives successfully here, but UDP does not guarantee every arrival.':'TCP processes reception, ordering and acknowledgment and demultiplexes the stream by port. This animation shows delivery without drawing every TCP acknowledgment.';}else if(appLayer(l))description=udp?'The DNS service parses the query and can generate a response. This animation shows only the request direction.':'The HTTP service parses the request and processes the resource before responding. This animation shows only the request direction.';else description=l.id==='session'?'Manage session-related state according to application interaction rules.':'Interpret the agreed encoding or format to recover application content.';steps.push({title:`Receiver · ${l.name}`,description,layer:i,host:1,headers:headers.map(x=>({...x})),tag:appLayer(l)?'Delivered successfully':l.unit});}
 return steps;
}
